const isSeoMeta = (m: any) => {
  if (m && typeof m.title === 'string') return true;
  const key = String(m?.property || m?.name || '').toLowerCase();
  return /^(description|robots|googlebot|og:|twitter:)/.test(key);
};
const isJsonLd = (s: any) => String(s?.type || '').toLowerCase() === 'application/ld+json';

// Preserve all non-SEO head entries, including CSS, preloads and any other scripts.
export function preserveProductionSeo(path: string, originalHead: (...args: any[]) => any, enabled = true) {
  return (...args: any[]) => {
    const original = originalHead(...args);
    if (!enabled) return original; // Explicitly retain waitlist-mode SEO.
    const prod = seoSnapshot[path];
    if (!prod) return original;
    return {
      ...original,
      meta: [...(original?.meta || []).filter((x: any) => !isSeoMeta(x)), ...prod.meta],
      links: [...(original?.links || []).filter((x: any) => !/\bcanonical\b/i.test(String(x?.rel || ''))), { rel: 'canonical', href: prod.canonical }],
      scripts: [...(original?.scripts || []).filter((x: any) => !isJsonLd(x)), ...prod.routeJsonLd.map((x: any) => ({ type: 'application/ld+json', children: JSON.stringify(x) }))],
    };
  };
}

// Original common Organization JSON-LD appears in the root on every page.
export function preserveProductionRootScripts(originalHead: (...args: any[]) => any) {
  return (...args: any[]) => {
    const original = originalHead(...args);
    return { ...original, scripts: [
      ...(original?.scripts || []).filter((x: any) => !isJsonLd(x)),
      ...commonRootJsonLd.map((x: any) => ({ type: 'application/ld+json', children: JSON.stringify(x) })),
    ]};
  };
}
